#!/usr/bin/env bash
set -euo pipefail

P10K_REPO="https://github.com/romkatv/powerlevel10k.git"
P10K_COMMIT="9253fb1c5034410c43a0c681ff8294181c54016c"
TIMESTAMP="$(date +%Y%m%d-%H%M%S)"

log() {
  printf '[p10k-installer] %s\n' "$*"
}

fail() {
  printf '[p10k-installer] ERROR: %s\n' "$*" >&2
  exit 1
}

run_privileged() {
  if [ "$(id -u)" -eq 0 ]; then
    "$@"
  elif command -v sudo >/dev/null 2>&1; then
    sudo "$@"
  else
    fail "Need root or sudo to install packages/change shell."
  fi
}

install_packages() {
  if command -v zsh >/dev/null 2>&1 && command -v git >/dev/null 2>&1; then
    return
  fi

  log "Installing required packages: zsh git"
  if command -v apt-get >/dev/null 2>&1; then
    run_privileged env DEBIAN_FRONTEND=noninteractive apt-get update
    run_privileged env DEBIAN_FRONTEND=noninteractive apt-get install -y zsh git ca-certificates
  elif command -v dnf >/dev/null 2>&1; then
    run_privileged dnf install -y zsh git ca-certificates
  elif command -v yum >/dev/null 2>&1; then
    run_privileged yum install -y zsh git ca-certificates
  elif command -v pacman >/dev/null 2>&1; then
    run_privileged pacman -Sy --noconfirm zsh git ca-certificates
  elif command -v apk >/dev/null 2>&1; then
    run_privileged apk add --no-cache zsh git ca-certificates
  else
    fail "Unsupported package manager. Install zsh and git, then rerun this script."
  fi
}

resolve_target() {
  TARGET_USER="${TARGET_USER:-${SUDO_USER:-$(id -un)}}"
  if [ -z "$TARGET_USER" ]; then
    TARGET_USER="$(id -un)"
  fi

  HOME_DIR="${TARGET_HOME:-$(getent passwd "$TARGET_USER" | cut -d: -f6 || true)}"
  if [ -z "$HOME_DIR" ]; then
    HOME_DIR="${HOME:-}"
  fi
  [ -n "$HOME_DIR" ] || fail "Cannot resolve target home directory."

  TARGET_GROUP="$(id -gn "$TARGET_USER" 2>/dev/null || printf '%s' "$TARGET_USER")"
}

backup_file() {
  file="$1"
  if [ -e "$file" ] || [ -L "$file" ]; then
    cp -a "$file" "$file.backup.$TIMESTAMP"
    log "Backup created: $file.backup.$TIMESTAMP"
  fi
}

extract_domain_from_file() {
  local file="$1"
  [ -r "$file" ] || return 1

  grep -Eio '([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}' "$file" 2>/dev/null \
    | grep -Eiv '^(example\.com|localhost\.localdomain)$' \
    | head -n 1
}

normalize_domain() {
  local domain="$1"

  domain="${domain#http://}"
  domain="${domain#https://}"
  domain="${domain#\*.}"
  domain="${domain%%/*}"
  domain="${domain%%:*}"
  domain="${domain%.}"
  printf '%s\n' "$domain" | tr '[:upper:]' '[:lower:]'
}

detect_domain() {
  local domain=""

  if [ -n "${P10K_DOMAIN:-}" ]; then
    normalize_domain "$P10K_DOMAIN"
    return 0
  fi

  domain="$(extract_domain_from_file /etc/xray/domain || true)"
  if [ -n "$domain" ]; then
    normalize_domain "$domain"
    return 0
  fi

  return 1
}

hostname_from_domain() {
  local domain="$1"
  local host

  host="${domain%%.*}"
  host="$(printf '%s\n' "$host" \
    | tr '[:upper:]' '[:lower:]' \
    | sed -E 's/[^a-z0-9-]+/-/g; s/^-+//; s/-+$//; s/-+/-/g')"
  host="${host:0:63}"
  host="${host%-}"

  [ -n "$host" ] || return 1
  printf '%s\n' "$host"
}

ensure_hosts_entry() {
  local new_host="$1"
  local tmp

  [ -r /etc/hosts ] || return 0
  tmp="$(mktemp)"

  if grep -Eq '^127\.0\.1\.1[[:space:]]+' /etc/hosts 2>/dev/null; then
    awk -v host="$new_host" '
      BEGIN { done = 0 }
      /^127\.0\.1\.1[[:space:]]+/ && !done {
        print "127.0.1.1\t" host
        done = 1
        next
      }
      /^127\.0\.1\.1[[:space:]]+/ { next }
      { print }
    ' /etc/hosts > "$tmp"
  else
    cat /etc/hosts > "$tmp"
    printf '127.0.1.1\t%s\n' "$new_host" >> "$tmp"
  fi

  run_privileged cp "$tmp" /etc/hosts
  rm -f "$tmp"
}

set_hostname_from_domain() {
  case "${P10K_SET_HOSTNAME:-1}" in
    0|false|FALSE|no|NO|off|OFF)
      log "Hostname update skipped by P10K_SET_HOSTNAME=${P10K_SET_HOSTNAME:-0}"
      return
      ;;
  esac

  local domain=""
  local new_host=""
  local current_host=""
  local tmp=""

  domain="$(detect_domain || true)"
  if [ -z "$domain" ]; then
    log "Domain not found; hostname unchanged"
    return
  fi

  new_host="$(hostname_from_domain "$domain" || true)"
  if [ -z "$new_host" ]; then
    log "Cannot derive hostname from domain: $domain"
    return
  fi

  current_host="$(hostnamectl --static 2>/dev/null || hostname 2>/dev/null || true)"
  if [ "$current_host" = "$new_host" ]; then
    log "Hostname already set to $new_host from domain $domain"
    return
  fi

  log "Setting hostname to $new_host from domain $domain"
  if command -v hostnamectl >/dev/null 2>&1; then
    run_privileged hostnamectl set-hostname "$new_host"
  else
    tmp="$(mktemp)"
    printf '%s\n' "$new_host" > "$tmp"
    run_privileged cp "$tmp" /etc/hostname
    rm -f "$tmp"
    run_privileged hostname "$new_host" 2>/dev/null || true
  fi
  ensure_hosts_entry "$new_host"
}

ensure_powerlevel10k() {
  P10K_DIR="$HOME_DIR/powerlevel10k"

  if [ -e "$P10K_DIR" ] && [ ! -d "$P10K_DIR/.git" ]; then
    mv "$P10K_DIR" "$P10K_DIR.backup.$TIMESTAMP"
    log "Moved existing non-git Powerlevel10k path to $P10K_DIR.backup.$TIMESTAMP"
  fi

  if [ ! -d "$P10K_DIR/.git" ]; then
    log "Cloning Powerlevel10k"
    git clone --depth=1 "$P10K_REPO" "$P10K_DIR"
  fi

  git -C "$P10K_DIR" remote set-url origin "$P10K_REPO" 2>/dev/null || true
  if git -C "$P10K_DIR" fetch --depth=1 origin "$P10K_COMMIT" >/dev/null 2>&1; then
    git -C "$P10K_DIR" checkout --force FETCH_HEAD >/dev/null
    log "Powerlevel10k pinned at $P10K_COMMIT"
  else
    log "Could not fetch pinned commit; using current upstream checkout"
    git -C "$P10K_DIR" pull --ff-only >/dev/null 2>&1 || true
  fi
}

write_zshrc() {
  backup_file "$HOME_DIR/.zshrc"
  cat > "$HOME_DIR/.zshrc" <<'ZSHRC'
# ~/.zshrc: executed by zsh for interactive shells.

export PATH="$HOME/.local/bin:$PATH"

HISTFILE="$HOME/.zsh_history"
HISTSIZE=10000
SAVEHIST=10000
setopt append_history share_history hist_ignore_dups

autoload -Uz compinit
compinit

source "$HOME/powerlevel10k/powerlevel10k.zsh-theme"

[[ ! -f "$HOME/.p10k.zsh" ]] || source "$HOME/.p10k.zsh"
ZSHRC
}

write_zlogin() {
  backup_file "$HOME_DIR/.zlogin"
  cat > "$HOME_DIR/.zlogin" <<'ZLOGIN'
# ~/.zlogin: executed by zsh login shells after ~/.zshrc.

if [[ -o interactive && -z "${P10K_MENU_SHOWN:-}" ]]; then
  export P10K_MENU_SHOWN=1
  case "${P10K_AUTO_MENU:-1}" in
    0|false|FALSE|no|NO|off|OFF) ;;
    *)
      if [[ -x /usr/local/bin/menu ]]; then
        print -r -- "Loading menu..."
        /usr/bin/env bash /usr/local/bin/menu
      fi
      ;;
  esac
fi
ZLOGIN
}

decode_base64() {
  if base64 -d </dev/null >/dev/null 2>&1; then
    base64 -d
  else
    base64 -D
  fi
}

