patch_menu_script() {
  local menu_file="/usr/local/bin/menu"
  local tmp=""
  local patched=""

  if [ ! -f "$menu_file" ]; then
    log "Menu script not found at $menu_file; menu patch skipped"
    return
  fi

  tmp="$(mktemp)"
  patched="$(mktemp)"
  cp "$menu_file" "$tmp"

  if ! grep -q 'curl_quick()' "$tmp"; then
    awk '
      { print }
      /^domain=\$\(cat \/usr\/local\/etc\/xray\/domain\)/ {
        print "curl_quick() {"
        print "    curl -fsS --connect-timeout 1 --max-time 2 \"\$@\" 2>/dev/null"
        print "}"
      }
    ' "$tmp" > "$patched"
    mv "$patched" "$tmp"
  fi

  awk '
    /^IPVPS=\$\(curl -s ipv4\.icanhazip\.com \|\| curl -s ipinfo\.io\/ip \|\| curl -s ifconfig\.me\)$/ {
      print "IPVPS=$(curl_quick https://ipv4.icanhazip.com || curl_quick https://ipinfo.io/ip || curl_quick https://ifconfig.me || true)"
      print "IPVPS=\"${IPVPS//$'\''\\n'\''/}\""
      print "[ -n \"$IPVPS\" ] || IPVPS=\"N/A\""
      next
    }
    /^IPV6=\$\(curl -s -6 ipv6\.icanhazip\.com\)$/ {
      print "IPV6=$(curl_quick -6 https://ipv6.icanhazip.com || true)"
      print "IPV6=\"${IPV6//$'\''\\n'\''/}\""
      next
    }
    { print }
  ' "$tmp" > "$patched"
  mv "$patched" "$tmp"

  if cmp -s "$menu_file" "$tmp"; then
    log "Menu script already patched"
    rm -f "$tmp" "$patched"
    return
  fi

  backup_file "$menu_file"
  run_privileged cp "$tmp" "$menu_file"
  run_privileged chmod +x "$menu_file"
  rm -f "$tmp" "$patched"
  log "Patched menu script curl timeouts in $menu_file"
}

fix_ownership() {
  if [ "$(id -u)" -eq 0 ]; then
    chown -R "$TARGET_USER:$TARGET_GROUP" "$HOME_DIR/.zshrc" "$HOME_DIR/.zlogin" "$HOME_DIR/.p10k.zsh" "$HOME_DIR/powerlevel10k"
  fi
}

set_default_shell() {
  ZSH_BIN="$(command -v zsh)"
  [ -n "$ZSH_BIN" ] || fail "zsh not found after installation."

  if [ "$(id -u)" -eq 0 ]; then
    if [ -w /etc/shells ] && ! grep -qxF "$ZSH_BIN" /etc/shells; then
      printf '%s\n' "$ZSH_BIN" >> /etc/shells
    fi

    if command -v usermod >/dev/null 2>&1; then
      usermod --shell "$ZSH_BIN" "$TARGET_USER"
    elif command -v chsh >/dev/null 2>&1; then
      chsh -s "$ZSH_BIN" "$TARGET_USER"
    else
      log "Could not change default shell automatically; set it manually to $ZSH_BIN"
      return
    fi
  elif command -v chsh >/dev/null 2>&1; then
    chsh -s "$ZSH_BIN" || log "Could not change default shell automatically; set it manually to $ZSH_BIN"
  else
    log "Could not change default shell automatically; set it manually to $ZSH_BIN"
  fi
}

restart_into_zsh() {
  case "${P10K_AUTO_EXEC_ZSH:-1}" in
    0|false|FALSE|no|NO|off|OFF)
      log "Auto exec zsh skipped by P10K_AUTO_EXEC_ZSH=${P10K_AUTO_EXEC_ZSH:-0}"
      return
      ;;
  esac

  if [ ! -t 0 ] || [ ! -t 1 ]; then
    log "Non-interactive shell detected; restart manually with: exec zsh"
    return
  fi

  ZSH_BIN="$(command -v zsh)"
  [ -n "$ZSH_BIN" ] || fail "zsh not found after installation."

  if [ "$(id -un)" != "$TARGET_USER" ]; then
    log "Installed for $TARGET_USER; current user is $(id -un). Restart manually as $TARGET_USER with: exec zsh"
    return
  fi

  log "Restarting current shell with: exec zsh"
  exec "$ZSH_BIN" -il
}

main() {
  resolve_target
  log "Target user: $TARGET_USER"
  log "Target home: $HOME_DIR"

  install_packages
  ensure_powerlevel10k
  write_zshrc
  write_zlogin
  write_p10k_config
  patch_menu_script
  fix_ownership
  set_default_shell
  set_hostname_from_domain

  log "Done. Restart with: exec zsh"
  log "Config installed: $HOME_DIR/.zshrc, $HOME_DIR/.zlogin and $HOME_DIR/.p10k.zsh"
  restart_into_zsh
}

main "$@"
